insert into public.question_sources (id, kind, label, licence_note, rights_holder, rights_status, verified_by, verified_at)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900019', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'easy', 'published', 'Qual conjunto é um subespaço de $\mathbb R^2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000191', '40000000-0000-4000-8000-000000900019', 'A', '$\{(x,y):x-2y=0\}$', 1), ('50000000-0000-4000-8000-000009000192', '40000000-0000-4000-8000-000000900019', 'B', '$\{(x,y):x-2y=1\}$', 2), ('50000000-0000-4000-8000-000009000193', '40000000-0000-4000-8000-000000900019', 'C', '$\{(x,y):x\ge0\}$', 3), ('50000000-0000-4000-8000-000009000194', '40000000-0000-4000-8000-000000900019', 'D', '$\{(x,y):xy=0\}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900019', '50000000-0000-4000-8000-000009000191') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900019', '30000000-0000-4000-8000-000000090006', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000191', '40000000-0000-4000-8000-000000900019', 'Um subespaço precisa conter o vetor nulo.', 1), ('60000000-0000-4000-8000-000009000192', '40000000-0000-4000-8000-000000900019', 'Equações lineares homogêneas descrevem núcleos de transformações lineares.', 2), ('60000000-0000-4000-8000-000009000193', '40000000-0000-4000-8000-000000900019', 'Confira também se somas e múltiplos permanecem no conjunto.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900019', '$\{(x,y):x-2y=0\}$', 'O conjunto solução de uma equação linear homogênea contém o zero e é fechado por soma e multiplicação escalar. Os demais conjuntos falham em pelo menos uma dessas condições.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000191', '40000000-0000-4000-8000-000000900019', 'Teste o vetor nulo', 'A igualdade $0-2\cdot0=0$ é verdadeira.', 1), ('70000000-0000-4000-8000-000009000192', '40000000-0000-4000-8000-000000900019', 'Teste a soma', 'Se $x_1-2y_1=0$ e $x_2-2y_2=0$, então $(x_1+x_2)-2(y_1+y_2)=0$.', 2), ('70000000-0000-4000-8000-000009000193', '40000000-0000-4000-8000-000000900019', 'Teste escalares', 'Multiplicar uma solução por $c$ mantém a igualdade homogênea.', 3), ('70000000-0000-4000-8000-000009000194', '40000000-0000-4000-8000-000000900019', 'Compare os demais', 'O segundo não contém zero; os dois últimos não são fechados pelas operações.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900020', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'easy', 'published', 'Seja $L=\operatorname{span}\{(2,-1)\}\subset\mathbb R^2$. Qual vetor pertence a $L$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000201', '40000000-0000-4000-8000-000000900020', 'A', '$(2,1)$', 1), ('50000000-0000-4000-8000-000009000202', '40000000-0000-4000-8000-000000900020', 'B', '$(6,-3)$', 2), ('50000000-0000-4000-8000-000009000203', '40000000-0000-4000-8000-000000900020', 'C', '$(6,3)$', 3), ('50000000-0000-4000-8000-000009000204', '40000000-0000-4000-8000-000000900020', 'D', '$(-2,-2)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900020', '50000000-0000-4000-8000-000009000202') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900020', '30000000-0000-4000-8000-000000090007', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000201', '40000000-0000-4000-8000-000000900020', 'Um vetor em $L$ precisa ser múltiplo de $(2,-1)$.', 1), ('60000000-0000-4000-8000-000009000202', '40000000-0000-4000-8000-000000900020', 'Teste se o mesmo escalar transforma as duas componentes.', 2), ('60000000-0000-4000-8000-000009000203', '40000000-0000-4000-8000-000000900020', 'Procure um múltiplo inteiro simples do gerador.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900020', '$(6,-3)$', 'Um subespaço gerado por um único vetor é a reta formada por todos os seus múltiplos escalares. É preciso verificar as duas componentes com o mesmo escalar.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000201', '40000000-0000-4000-8000-000000900020', 'Use a definição de gerador', '$L=\{c(2,-1):c\in\mathbb R\}$.', 1), ('70000000-0000-4000-8000-000009000202', '40000000-0000-4000-8000-000000900020', 'Teste a primeira alternativa', '$3(2,-1)=(6,-3)$.', 2), ('70000000-0000-4000-8000-000009000203', '40000000-0000-4000-8000-000000900020', 'Verifique as duas componentes', 'O mesmo escalar $3$ produz simultaneamente $6$ e $-3$.', 3), ('70000000-0000-4000-8000-000009000204', '40000000-0000-4000-8000-000000900020', 'Elimine os demais', 'Eles não são múltiplos de $(2,-1)$ com um único escalar.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900021', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'easy', 'published', 'Qual conjunto é necessariamente linearmente dependente?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000211', '40000000-0000-4000-8000-000000900021', 'A', '$\{(1,1),(1,-1)\}$', 1), ('50000000-0000-4000-8000-000009000212', '40000000-0000-4000-8000-000000900021', 'B', '$\{(2,1)\}$', 2), ('50000000-0000-4000-8000-000009000213', '40000000-0000-4000-8000-000000900021', 'C', '$\{(1,0),(0,0)\}$', 3), ('50000000-0000-4000-8000-000009000214', '40000000-0000-4000-8000-000000900021', 'D', '$\{(1,0),(0,1)\}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900021', '50000000-0000-4000-8000-000009000213') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900021', '30000000-0000-4000-8000-000000090008', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000211', '40000000-0000-4000-8000-000000900021', 'Dependência significa existir uma combinação nula com coeficientes não todos nulos.', 1), ('60000000-0000-4000-8000-000009000212', '40000000-0000-4000-8000-000000900021', 'Observe se algum vetor pode receber coeficiente não nulo sem alterar a soma.', 2), ('60000000-0000-4000-8000-000009000213', '40000000-0000-4000-8000-000000900021', 'Um conjunto que contém o vetor nulo tem uma relação imediata.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900021', '$\{(1,0),(0,0)\}$', 'Se o vetor zero pertence ao conjunto, basta atribuir a ele um coeficiente não nulo e zero aos demais para obter uma combinação nula não trivial. Isso prova dependência.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000211', '40000000-0000-4000-8000-000000900021', 'Use a definição', 'Procure coeficientes não todos zero cuja combinação seja o vetor nulo.', 1), ('70000000-0000-4000-8000-000009000212', '40000000-0000-4000-8000-000000900021', 'Explore o vetor nulo', '$0(1,0)+1(0,0)=(0,0)$.', 2), ('70000000-0000-4000-8000-000009000213', '40000000-0000-4000-8000-000000900021', 'Observe os coeficientes', 'O segundo coeficiente vale $1$, então a relação não é trivial.', 3), ('70000000-0000-4000-8000-000009000214', '40000000-0000-4000-8000-000000900021', 'Conclua', 'O primeiro conjunto é dependente independentemente de qualquer cálculo adicional.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900022', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'easy', 'published', 'Qual par forma uma base de $\mathbb R^2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000221', '40000000-0000-4000-8000-000000900022', 'A', '$\{(1,2),(2,4)\}$', 1), ('50000000-0000-4000-8000-000009000222', '40000000-0000-4000-8000-000000900022', 'B', '$\{(0,0),(1,0)\}$', 2), ('50000000-0000-4000-8000-000009000223', '40000000-0000-4000-8000-000000900022', 'C', '$\{(2,2),(-1,-1)\}$', 3), ('50000000-0000-4000-8000-000009000224', '40000000-0000-4000-8000-000000900022', 'D', '$\{(1,1),(1,-1)\}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900022', '50000000-0000-4000-8000-000009000224') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900022', '30000000-0000-4000-8000-000000090009', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000221', '40000000-0000-4000-8000-000000900022', 'Em $\mathbb R^2$, dois vetores formam base quando são independentes.', 1), ('60000000-0000-4000-8000-000009000222', '40000000-0000-4000-8000-000000900022', 'Coloque os vetores como colunas de uma matriz $2\times2$.', 2), ('60000000-0000-4000-8000-000009000223', '40000000-0000-4000-8000-000000900022', 'Um determinante não nulo confirma a independência.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900022', '$\{(1,1),(1,-1)\}$', 'Uma base de $\mathbb R^2$ precisa ter dois vetores linearmente independentes. O primeiro par tem determinante não nulo; nos demais, há vetor zero ou vetores proporcionais.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000221', '40000000-0000-4000-8000-000000900022', 'Monte a matriz', '$\begin{pmatrix}1&1\\1&-1\end{pmatrix}$.', 1), ('70000000-0000-4000-8000-000009000222', '40000000-0000-4000-8000-000000900022', 'Calcule o determinante', '$1\cdot(-1)-1\cdot1=-2$.', 2), ('70000000-0000-4000-8000-000009000223', '40000000-0000-4000-8000-000000900022', 'Interprete', 'Como o determinante é não nulo, as colunas são independentes.', 3), ('70000000-0000-4000-8000-000009000224', '40000000-0000-4000-8000-000000900022', 'Conclua a geração', 'Dois vetores independentes em $\mathbb R^2$ também geram todo o espaço.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900023', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'easy', 'published', 'Qual é a dimensão do espaço $P_2$ dos polinômios reais de grau menor ou igual a $2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000231', '40000000-0000-4000-8000-000000900023', 'A', '$3$', 1), ('50000000-0000-4000-8000-000009000232', '40000000-0000-4000-8000-000000900023', 'B', '$2$', 2), ('50000000-0000-4000-8000-000009000233', '40000000-0000-4000-8000-000000900023', 'C', '$1$', 3), ('50000000-0000-4000-8000-000009000234', '40000000-0000-4000-8000-000000900023', 'D', '$4$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900023', '50000000-0000-4000-8000-000009000231') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900023', '30000000-0000-4000-8000-000000090009', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000231', '40000000-0000-4000-8000-000000900023', 'Escreva a forma geral de um polinômio desse espaço.', 1), ('60000000-0000-4000-8000-000009000232', '40000000-0000-4000-8000-000000900023', 'Conte quantos coeficientes podem variar independentemente.', 2), ('60000000-0000-4000-8000-000009000233', '40000000-0000-4000-8000-000000900023', 'A base padrão começa com $1$ e termina em $x^2$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900023', '$3$', 'Cada polinômio de $P_2$ é determinado por três coeficientes reais independentes. A base padrão contém $1$, $x$ e $x^2$, portanto possui três elementos.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000231', '40000000-0000-4000-8000-000000900023', 'Escreva um elemento geral', '$p(x)=a+bx+cx^2$.', 1), ('70000000-0000-4000-8000-000009000232', '40000000-0000-4000-8000-000000900023', 'Separe os geradores', '$p=acdot1+bcdot x+ccdot x^2$.', 2), ('70000000-0000-4000-8000-000009000233', '40000000-0000-4000-8000-000000900023', 'Verifique independência', 'Nenhuma combinação não trivial de $1,x,x^2$ é o polinômio zero.', 3), ('70000000-0000-4000-8000-000009000234', '40000000-0000-4000-8000-000000900023', 'Conte a base', 'A base tem três vetores, logo $dim P_2=3$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900024', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'easy', 'published', 'Para $A=\begin{pmatrix}1&2&0\\0&0&1\end{pmatrix}$, qual conjunto é uma base de $\operatorname{Col}(A)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000241', '40000000-0000-4000-8000-000000900024', 'A', '$\{(1,0),(2,0),(0,1)\}$', 1), ('50000000-0000-4000-8000-000009000242', '40000000-0000-4000-8000-000000900024', 'B', '$\{(1,0),(0,1)\}$', 2), ('50000000-0000-4000-8000-000009000243', '40000000-0000-4000-8000-000000900024', 'C', '$\{(1,0),(2,0)\}$', 3), ('50000000-0000-4000-8000-000009000244', '40000000-0000-4000-8000-000000900024', 'D', '$\{(2,0),(0,1)\}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900024', '50000000-0000-4000-8000-000009000242') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900024', '30000000-0000-4000-8000-000000090010', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000241', '40000000-0000-4000-8000-000000900024', 'O espaço coluna é gerado pelas colunas da matriz original.', 1), ('60000000-0000-4000-8000-000009000242', '40000000-0000-4000-8000-000000900024', 'Elimine colunas que são múltiplas de outras.', 2), ('60000000-0000-4000-8000-000009000243', '40000000-0000-4000-8000-000000900024', 'A primeira e a terceira colunas apontam em direções distintas.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900024', '$\{(1,0),(0,1)\}$', 'As colunas primeira e terceira são independentes e já geram as duas direções de $\mathbb R^2$. A segunda coluna é duas vezes a primeira e não acrescenta dimensão.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000241', '40000000-0000-4000-8000-000000900024', 'Liste as colunas', '$c_1=(1,0)$, $c_2=(2,0)$ e $c_3=(0,1)$.', 1), ('70000000-0000-4000-8000-000009000242', '40000000-0000-4000-8000-000000900024', 'Remova a redundância', '$c_2=2c_1$.', 2), ('70000000-0000-4000-8000-000009000243', '40000000-0000-4000-8000-000000900024', 'Verifique as restantes', '$c_1$ e $c_3$ são independentes.', 3), ('70000000-0000-4000-8000-000009000244', '40000000-0000-4000-8000-000000900024', 'Forme a base', 'Assim, ${c_1,c_3}$ é uma base de $\operatorname{Col}(A)$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900025', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'medium', 'published', 'Sejam $U=\{(x,0):x\in\mathbb R\}$ e $V=\{(0,y):y\in\mathbb R\}$. Por que $U\cup V$ não é subespaço de $\mathbb R^2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000251', '40000000-0000-4000-8000-000000900025', 'A', 'Não é fechado por opostos.', 1), ('50000000-0000-4000-8000-000009000252', '40000000-0000-4000-8000-000000900025', 'B', 'Não contém vetores não nulos.', 2), ('50000000-0000-4000-8000-000009000253', '40000000-0000-4000-8000-000000900025', 'C', 'Não é fechado por soma.', 3), ('50000000-0000-4000-8000-000009000254', '40000000-0000-4000-8000-000000900025', 'D', 'Não contém o vetor nulo.', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900025', '50000000-0000-4000-8000-000009000253') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900025', '30000000-0000-4000-8000-000000090006', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000251', '40000000-0000-4000-8000-000000900025', 'Procure um vetor simples em cada eixo.', 1), ('60000000-0000-4000-8000-000009000252', '40000000-0000-4000-8000-000000900025', 'Some um elemento de $U$ com um elemento de $V$.', 2), ('60000000-0000-4000-8000-000009000253', '40000000-0000-4000-8000-000000900025', 'Confira se o resultado permanece sobre algum dos dois eixos.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900025', 'Não é fechado por soma.', 'A união contém cada eixo separadamente, mas um vetor de um eixo somado a um vetor do outro geralmente sai de ambos. A soma de subespaços, ao contrário da união, incluiria essas combinações.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000251', '40000000-0000-4000-8000-000000900025', 'Escolha elementos', 'Temos $(1,0)\in U$ e $(0,1)\in V$.', 1), ('70000000-0000-4000-8000-000009000252', '40000000-0000-4000-8000-000000900025', 'Some', 'A soma é $(1,1)$.', 2), ('70000000-0000-4000-8000-000009000253', '40000000-0000-4000-8000-000000900025', 'Teste a união', 'O vetor $(1,1)$ não pertence a $U$ nem a $V$.', 3), ('70000000-0000-4000-8000-000009000254', '40000000-0000-4000-8000-000000900025', 'Conclua', 'A união falha no fechamento por soma e não é subespaço.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900026', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'medium', 'published', 'O vetor $w=(4,1,5)$ pertence a $\operatorname{span}\{(1,0,1),(0,1,1)\}$. Qual combinação o produz?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000261', '40000000-0000-4000-8000-000000900026', 'A', '$u+4v$', 1), ('50000000-0000-4000-8000-000009000262', '40000000-0000-4000-8000-000000900026', 'B', '$4u-v$', 2), ('50000000-0000-4000-8000-000009000263', '40000000-0000-4000-8000-000000900026', 'C', '$5u+v$', 3), ('50000000-0000-4000-8000-000009000264', '40000000-0000-4000-8000-000000900026', 'D', '$4u+v$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900026', '50000000-0000-4000-8000-000009000264') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900026', '30000000-0000-4000-8000-000000090007', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000261', '40000000-0000-4000-8000-000000900026', 'Use as duas primeiras coordenadas para determinar os coeficientes.', 1), ('60000000-0000-4000-8000-000009000262', '40000000-0000-4000-8000-000000900026', 'Depois confira a terceira coordenada, em vez de presumir pertinência.', 2), ('60000000-0000-4000-8000-000009000263', '40000000-0000-4000-8000-000000900026', 'Nomeie os geradores como $u$ e $v$.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900026', '$4u+v$', 'As primeiras coordenadas fixam os coeficientes da combinação, e a terceira serve como teste de compatibilidade. Aqui o mesmo par de coeficientes reproduz todas as entradas.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000261', '40000000-0000-4000-8000-000000900026', 'Escreva a combinação', '$au+bv=(a,b,a+b)$.', 1), ('70000000-0000-4000-8000-000009000262', '40000000-0000-4000-8000-000000900026', 'Compare as primeiras entradas', '$a=4$ e $b=1$.', 2), ('70000000-0000-4000-8000-000009000263', '40000000-0000-4000-8000-000000900026', 'Confira a terceira', '$a+b=4+1=5$, como em $w$.', 3), ('70000000-0000-4000-8000-000009000264', '40000000-0000-4000-8000-000000900026', 'Conclua', 'Logo $w=4u+v$ e pertence ao espaço gerado.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900027', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'medium', 'published', 'Os vetores $(1,0,1)$, $(0,1,1)$ e $(1,1,a)$ são linearmente dependentes para qual valor de $a$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000271', '40000000-0000-4000-8000-000000900027', 'A', '$a=2$', 1), ('50000000-0000-4000-8000-000009000272', '40000000-0000-4000-8000-000000900027', 'B', '$a=0$', 2), ('50000000-0000-4000-8000-000009000273', '40000000-0000-4000-8000-000000900027', 'C', '$a=1$', 3), ('50000000-0000-4000-8000-000009000274', '40000000-0000-4000-8000-000000900027', 'D', '$a=-2$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900027', '50000000-0000-4000-8000-000009000271') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900027', '30000000-0000-4000-8000-000000090008', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000271', '40000000-0000-4000-8000-000000900027', 'Observe a soma dos dois primeiros vetores.', 1), ('60000000-0000-4000-8000-000009000272', '40000000-0000-4000-8000-000000900027', 'Compare essa soma com o terceiro vetor.', 2), ('60000000-0000-4000-8000-000009000273', '40000000-0000-4000-8000-000000900027', 'Alternativamente, use o determinante da matriz com esses vetores como colunas.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900027', '$a=2$', 'A dependência ocorre quando o terceiro vetor entra no plano gerado pelos dois primeiros. Sua primeira e segunda coordenadas já exigem a soma desses vetores, fixando a terceira coordenada.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000271', '40000000-0000-4000-8000-000000900027', 'Some os primeiros vetores', '$(1,0,1)+(0,1,1)=(1,1,2)$.', 1), ('70000000-0000-4000-8000-000009000272', '40000000-0000-4000-8000-000000900027', 'Compare com o terceiro', 'O terceiro é $(1,1,a)$.', 2), ('70000000-0000-4000-8000-000009000273', '40000000-0000-4000-8000-000000900027', 'Imponha a igualdade', 'Eles coincidem exatamente quando $a=2$.', 3), ('70000000-0000-4000-8000-000009000274', '40000000-0000-4000-8000-000000900027', 'Exiba a relação', 'Nesse caso, $v_1+v_2-v_3=0$ é uma relação não trivial.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900028', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'medium', 'published', 'O conjunto $S=\{(1,0,1),(0,1,1)\}$ é independente em $\mathbb R^3$. Qual vetor pode ser acrescentado para formar uma base de $\mathbb R^3$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000281', '40000000-0000-4000-8000-000000900028', 'A', '$(-1,1,0)$', 1), ('50000000-0000-4000-8000-000009000282', '40000000-0000-4000-8000-000000900028', 'B', '$(0,0,1)$', 2), ('50000000-0000-4000-8000-000009000283', '40000000-0000-4000-8000-000000900028', 'C', '$(1,1,2)$', 3), ('50000000-0000-4000-8000-000009000284', '40000000-0000-4000-8000-000000900028', 'D', '$(2,0,2)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900028', '50000000-0000-4000-8000-000009000282') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900028', '30000000-0000-4000-8000-000000090009', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000281', '40000000-0000-4000-8000-000000900028', 'O terceiro vetor não pode pertencer ao plano gerado por $S$.', 1), ('60000000-0000-4000-8000-000009000282', '40000000-0000-4000-8000-000000900028', 'Um vetor gerado por $S$ tem a forma $(a,b,a+b)$.', 2), ('60000000-0000-4000-8000-000009000283', '40000000-0000-4000-8000-000000900028', 'Teste se a terceira coordenada do candidato é a soma das duas primeiras.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900028', '$(0,0,1)$', 'Os vetores gerados por $S$ satisfazem $z=x+y$. O candidato $(0,0,1)$ viola essa equação, portanto está fora do plano e amplia o conjunto independente para três vetores.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000281', '40000000-0000-4000-8000-000000900028', 'Descreva o plano gerado', '$a(1,0,1)+b(0,1,1)=(a,b,a+b)$.', 1), ('70000000-0000-4000-8000-000009000282', '40000000-0000-4000-8000-000000900028', 'Teste o primeiro candidato', 'Para $(0,0,1)$, teríamos de ter $1=0+0$, o que é falso.', 2), ('70000000-0000-4000-8000-000009000283', '40000000-0000-4000-8000-000000900028', 'Conclua independência', 'Logo o candidato não está no espaço gerado pelos dois vetores.', 3), ('70000000-0000-4000-8000-000009000284', '40000000-0000-4000-8000-000000900028', 'Use a dimensão', 'Três vetores independentes em $\mathbb R^3$ formam uma base.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900029', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'medium', 'published', 'Uma transformação linear $T:\mathbb R^5\to\mathbb R^3$ tem posto $2$. Qual é a dimensão de $\ker T$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000291', '40000000-0000-4000-8000-000000900029', 'A', '$2$', 1), ('50000000-0000-4000-8000-000009000292', '40000000-0000-4000-8000-000000900029', 'B', '$5$', 2), ('50000000-0000-4000-8000-000009000293', '40000000-0000-4000-8000-000000900029', 'C', '$3$', 3), ('50000000-0000-4000-8000-000009000294', '40000000-0000-4000-8000-000000900029', 'D', '$1$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900029', '50000000-0000-4000-8000-000009000293') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900029', '30000000-0000-4000-8000-000000090010', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000291', '40000000-0000-4000-8000-000000900029', 'O teorema relaciona o domínio, o núcleo e a imagem.', 1), ('60000000-0000-4000-8000-000009000292', '40000000-0000-4000-8000-000000900029', 'Use a dimensão de $\mathbb R^5$, não a do contradomínio.', 2), ('60000000-0000-4000-8000-000009000293', '40000000-0000-4000-8000-000000900029', 'A nulidade completa o posto até a dimensão do domínio.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900029', '$3$', 'O teorema posto-nulidade usa a dimensão do domínio: dimensão do núcleo mais dimensão da imagem é igual a cinco. Como a imagem tem dimensão dois, restam três dimensões no núcleo.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000291', '40000000-0000-4000-8000-000000900029', 'Identifique os dados', '$dim(\mathbb R^5)=5$ e $\operatorname{posto}T=2$.', 1), ('70000000-0000-4000-8000-000009000292', '40000000-0000-4000-8000-000000900029', 'Aplique o teorema', '$dimker T+dimoperatorname{Im}T=5$.', 2), ('70000000-0000-4000-8000-000009000293', '40000000-0000-4000-8000-000000900029', 'Substitua o posto', '$dimker T+2=5$.', 3), ('70000000-0000-4000-8000-000009000294', '40000000-0000-4000-8000-000000900029', 'Conclua', '$dimker T=3$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900030', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'medium', 'published', 'Em um espaço vetorial finito, $\dim U=3$, $\dim V=2$ e $\dim(U+V)=4$. Quanto vale $\dim(U\cap V)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000301', '40000000-0000-4000-8000-000000900030', 'A', '$0$', 1), ('50000000-0000-4000-8000-000009000302', '40000000-0000-4000-8000-000000900030', 'B', '$2$', 2), ('50000000-0000-4000-8000-000009000303', '40000000-0000-4000-8000-000000900030', 'C', '$5$', 3), ('50000000-0000-4000-8000-000009000304', '40000000-0000-4000-8000-000000900030', 'D', '$1$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900030', '50000000-0000-4000-8000-000009000304') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900030', '30000000-0000-4000-8000-000000090013', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000301', '40000000-0000-4000-8000-000000900030', 'A dimensão da soma conta a interseção apenas uma vez.', 1), ('60000000-0000-4000-8000-000009000302', '40000000-0000-4000-8000-000000900030', 'Escreva a fórmula de Grassmann.', 2), ('60000000-0000-4000-8000-000009000303', '40000000-0000-4000-8000-000000900030', 'Isole a dimensão da interseção depois de substituir os três valores.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900030', '$1$', 'Ao somar as dimensões de $U$ e $V$, as direções comuns são contadas duas vezes. A fórmula dimensional subtrai exatamente a dimensão da interseção para corrigir essa duplicidade.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000301', '40000000-0000-4000-8000-000000900030', 'Escreva a relação', '$dim(U+V)=dim U+dim V-dim(Ucap V)$.', 1), ('70000000-0000-4000-8000-000009000302', '40000000-0000-4000-8000-000000900030', 'Substitua os dados', '$4=3+2-dim(Ucap V)$.', 2), ('70000000-0000-4000-8000-000009000303', '40000000-0000-4000-8000-000000900030', 'Isole a incógnita', '$dim(Ucap V)=5-4$.', 3), ('70000000-0000-4000-8000-000009000304', '40000000-0000-4000-8000-000000900030', 'Conclua', 'A interseção tem dimensão $1$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900031', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'hard', 'published', 'Considere o espaço $S$ das matrizes simétricas reais $2\times2$. Qual afirmação descreve corretamente uma base e a dimensão de $S$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000311', '40000000-0000-4000-8000-000000900031', 'A', '$\left\{\begin{pmatrix}1&0\\0&0\end{pmatrix},\begin{pmatrix}0&1\\1&0\end{pmatrix},\begin{pmatrix}0&0\\0&1\end{pmatrix}\right\}$ e dimensão $3$', 1), ('50000000-0000-4000-8000-000009000312', '40000000-0000-4000-8000-000000900031', 'B', 'As quatro matrizes unitárias e dimensão $4$', 2), ('50000000-0000-4000-8000-000009000313', '40000000-0000-4000-8000-000000900031', 'C', 'Duas matrizes diagonais e dimensão $2$', 3), ('50000000-0000-4000-8000-000009000314', '40000000-0000-4000-8000-000000900031', 'D', 'Uma matriz identidade e dimensão $1$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900031', '50000000-0000-4000-8000-000009000311') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900031', '30000000-0000-4000-8000-000000090009', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000311', '40000000-0000-4000-8000-000000900031', 'Escreva a forma geral de uma matriz simétrica $2\times2$.', 1), ('60000000-0000-4000-8000-000009000312', '40000000-0000-4000-8000-000000900031', 'As duas entradas fora da diagonal são obrigadas a ser iguais.', 2), ('60000000-0000-4000-8000-000009000313', '40000000-0000-4000-8000-000000900031', 'Separe um gerador para cada parâmetro livre.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900031', '$\left\{\begin{pmatrix}1&0\\0&0\end{pmatrix},\begin{pmatrix}0&1\\1&0\end{pmatrix},\begin{pmatrix}0&0\\0&1\end{pmatrix}\right\}$ e dimensão $3$', 'Uma matriz simétrica $2\times2$ possui três parâmetros independentes: duas entradas diagonais e uma entrada fora da diagonal compartilhada pelas posições simétricas. A base proposta isola esses parâmetros.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000311', '40000000-0000-4000-8000-000000900031', 'Parametrize o espaço', 'Toda matriz de $S$ é $\begin{pmatrix}a&b\\b&c\end{pmatrix}$.', 1), ('70000000-0000-4000-8000-000009000312', '40000000-0000-4000-8000-000000900031', 'Separe os parâmetros', 'Ela é $aE_{11}+b(E_{12}+E_{21})+cE_{22}$.', 2), ('70000000-0000-4000-8000-000009000313', '40000000-0000-4000-8000-000000900031', 'Verifique a base', 'Os três geradores são simétricos, independentes e geram toda matriz dessa forma.', 3), ('70000000-0000-4000-8000-000009000314', '40000000-0000-4000-8000-000000900031', 'Conte', 'Há três parâmetros livres e três vetores na base, então $dim S=3$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900032', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'hard', 'published', 'Seja $W=\{p\in P_3:p(1)=0\}$. Qual é a dimensão de $W$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000321', '40000000-0000-4000-8000-000000900032', 'A', '$1$', 1), ('50000000-0000-4000-8000-000009000322', '40000000-0000-4000-8000-000000900032', 'B', '$3$', 2), ('50000000-0000-4000-8000-000009000323', '40000000-0000-4000-8000-000000900032', 'C', '$4$', 3), ('50000000-0000-4000-8000-000009000324', '40000000-0000-4000-8000-000000900032', 'D', '$2$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900032', '50000000-0000-4000-8000-000009000322') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900032', '30000000-0000-4000-8000-000000090006', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000321', '40000000-0000-4000-8000-000000900032', 'Avaliar em $1$ define uma transformação linear de $P_3$ em $\mathbb R$.', 1), ('60000000-0000-4000-8000-000009000322', '40000000-0000-4000-8000-000000900032', 'O conjunto $W$ é o núcleo dessa transformação.', 2), ('60000000-0000-4000-8000-000009000323', '40000000-0000-4000-8000-000000900032', 'A avaliação não é a transformação nula, portanto sua imagem tem dimensão um.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900032', '$3$', 'O espaço $P_3$ tem dimensão quatro. A condição $p(1)=0$ é uma única restrição linear independente, ou equivalentemente o núcleo de um funcional não nulo, reduzindo a dimensão em uma unidade.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000321', '40000000-0000-4000-8000-000000900032', 'Defina o funcional', '$T:P_3	omathbb R$ por $T(p)=p(1)$.', 1), ('70000000-0000-4000-8000-000009000322', '40000000-0000-4000-8000-000000900032', 'Identifique o núcleo', '$W=ker T$.', 2), ('70000000-0000-4000-8000-000009000323', '40000000-0000-4000-8000-000000900032', 'Calcule o posto', 'Como $T(1)=1$, a imagem é $\mathbb R$ e tem dimensão $1$.', 3), ('70000000-0000-4000-8000-000009000324', '40000000-0000-4000-8000-000000900032', 'Aplique posto-nulidade', '$dim W=dim P_3-1=4-1=3$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900033', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'hard', 'published', 'Em $\mathbb R^3$, seja $U=\operatorname{span}\{(1,0,0),(0,1,0)\}$. Qual subespaço $V$ satisfaz $\mathbb R^3=U\oplus V$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000331', '40000000-0000-4000-8000-000000900033', 'A', '$V=\operatorname{span}\{(1,0,0),(0,0,1)\}$', 1), ('50000000-0000-4000-8000-000009000332', '40000000-0000-4000-8000-000000900033', 'B', '$V=U$', 2), ('50000000-0000-4000-8000-000009000333', '40000000-0000-4000-8000-000000900033', 'C', '$V=\operatorname{span}\{(0,0,1)\}$', 3), ('50000000-0000-4000-8000-000009000334', '40000000-0000-4000-8000-000000900033', 'D', '$V=\operatorname{span}\{(1,1,0)\}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900033', '50000000-0000-4000-8000-000009000333') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900033', '30000000-0000-4000-8000-000000090013', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000331', '40000000-0000-4000-8000-000000900033', 'Uma soma direta exige soma igual ao espaço todo e interseção apenas no zero.', 1), ('60000000-0000-4000-8000-000009000332', '40000000-0000-4000-8000-000000900033', 'O subespaço $U$ é o plano $z=0$.', 2), ('60000000-0000-4000-8000-000009000333', '40000000-0000-4000-8000-000000900033', 'Escolha uma direção fora desse plano, sem adicionar dimensão desnecessária.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900033', '$V=\operatorname{span}\{(0,0,1)\}$', 'O eixo $z$ fornece exatamente a direção ausente do plano $xy$. Sua interseção com $U$ é apenas o vetor zero, e as dimensões dois mais um completam todo o espaço tridimensional.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000331', '40000000-0000-4000-8000-000000900033', 'Interprete $U$', '$U={(x,y,0):x,yinmathbb R}$.', 1), ('70000000-0000-4000-8000-000009000332', '40000000-0000-4000-8000-000000900033', 'Teste a interseção', 'Um vetor do eixo $z$ que também tem $z=0$ só pode ser o vetor nulo.', 2), ('70000000-0000-4000-8000-000009000333', '40000000-0000-4000-8000-000000900033', 'Teste a soma', '$(x,y,z)=(x,y,0)+(0,0,z)$ para todo vetor de $\mathbb R^3$.', 3), ('70000000-0000-4000-8000-000009000334', '40000000-0000-4000-8000-000000900033', 'Conclua', 'A soma cobre o espaço e a decomposição é única, logo é direta.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900034', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'hard', 'published', 'As linhas de $A=\begin{pmatrix}1&1&0\\0&1&1\end{pmatrix}$ geram o espaço linha. Qual vetor gera $\operatorname{Nul}(A)$ e é ortogonal a esse espaço?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000341', '40000000-0000-4000-8000-000000900034', 'A', '$(1,1,1)$', 1), ('50000000-0000-4000-8000-000009000342', '40000000-0000-4000-8000-000000900034', 'B', '$(1,-1,-1)$', 2), ('50000000-0000-4000-8000-000009000343', '40000000-0000-4000-8000-000000900034', 'C', '$(0,1,-1)$', 3), ('50000000-0000-4000-8000-000009000344', '40000000-0000-4000-8000-000000900034', 'D', '$(1,-1,1)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900034', '50000000-0000-4000-8000-000009000344') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900034', '30000000-0000-4000-8000-000000090010', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000341', '40000000-0000-4000-8000-000000900034', 'Um vetor do núcleo deve satisfazer cada produto escalar com uma linha igual a zero.', 1), ('60000000-0000-4000-8000-000009000342', '40000000-0000-4000-8000-000000900034', 'Resolva $x+y=0$ e $y+z=0$.', 2), ('60000000-0000-4000-8000-000009000343', '40000000-0000-4000-8000-000000900034', 'Escolha um valor livre e confira as duas equações.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900034', '$(1,-1,1)$', 'A equação $Ax=0$ afirma que $x$ é ortogonal a cada linha de $A$. Resolver as duas relações fornece uma direção unidimensional, que é o complemento ortogonal do espaço linha.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000341', '40000000-0000-4000-8000-000000900034', 'Traduza o núcleo', '$x+y=0$ e $y+z=0$.', 1), ('70000000-0000-4000-8000-000009000342', '40000000-0000-4000-8000-000000900034', 'Parametrize', 'Tomando $y=-t$, obtemos $x=t$ e $z=t$.', 2), ('70000000-0000-4000-8000-000009000343', '40000000-0000-4000-8000-000000900034', 'Escolha um gerador', 'Com $t=1$, resulta $(1,-1,1)$.', 3), ('70000000-0000-4000-8000-000009000344', '40000000-0000-4000-8000-000000900034', 'Confira a ortogonalidade', 'Os produtos com $(1,1,0)$ e $(0,1,1)$ são ambos zero.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900035', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'hard', 'published', 'Um conjunto $S=\{v_1,v_2,v_3\}$ gera um espaço $V$, mas existe uma relação não trivial $2v_1-v_2+v_3=0$. O que isso implica sobre as representações por $S$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000351', '40000000-0000-4000-8000-000000900035', 'A', 'Todo vetor de $V$ possui mais de uma representação por $S$.', 1), ('50000000-0000-4000-8000-000009000352', '40000000-0000-4000-8000-000000900035', 'B', 'Nenhum vetor de $V$ pode ser representado.', 2), ('50000000-0000-4000-8000-000009000353', '40000000-0000-4000-8000-000000900035', 'C', 'Somente o vetor zero possui representação.', 3), ('50000000-0000-4000-8000-000009000354', '40000000-0000-4000-8000-000000900035', 'D', 'As representações continuam sempre únicas.', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900035', '50000000-0000-4000-8000-000009000351') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900035', '30000000-0000-4000-8000-000000090008', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000351', '40000000-0000-4000-8000-000000900035', 'A relação nula pode ser somada a qualquer combinação linear sem alterar o vetor produzido.', 1), ('60000000-0000-4000-8000-000009000352', '40000000-0000-4000-8000-000000900035', 'Comece com uma representação arbitrária de um vetor de $V$.', 2), ('60000000-0000-4000-8000-000009000353', '40000000-0000-4000-8000-000000900035', 'Altere os coeficientes por um múltiplo da relação dada.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900035', 'Todo vetor de $V$ possui mais de uma representação por $S$.', 'Como $S$ gera $V$, todo vetor tem ao menos uma representação. A relação não trivial permite modificar simultaneamente os três coeficientes sem mudar o resultado, destruindo a unicidade.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000351', '40000000-0000-4000-8000-000000900035', 'Tome uma representação', 'Escreva $w=a_1v_1+a_2v_2+a_3v_3$.', 1), ('70000000-0000-4000-8000-000009000352', '40000000-0000-4000-8000-000000900035', 'Some a relação nula', '$w=(a_1+2t)v_1+(a_2-t)v_2+(a_3+t)v_3$.', 2), ('70000000-0000-4000-8000-000009000353', '40000000-0000-4000-8000-000000900035', 'Escolha parâmetros distintos', 'Valores diferentes de $t$ produzem triplas de coeficientes diferentes.', 3), ('70000000-0000-4000-8000-000009000354', '40000000-0000-4000-8000-000000900035', 'Conclua', 'Como a relação vale para qualquer $w$, nenhuma representação por $S$ é única.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000900036', '20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000090002', 'multiple_choice', 'hard', 'published', 'Suponha que $Ax=b$ seja consistente e que $b\ne0$. Se $x_p$ é uma solução particular, qual descrição correta do conjunto de soluções evidencia que ele geralmente não é subespaço?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009000361', '40000000-0000-4000-8000-000000900036', 'A', '$x_p\operatorname{Nul}(A)$', 1), ('50000000-0000-4000-8000-000009000362', '40000000-0000-4000-8000-000000900036', 'B', '$x_p+\operatorname{Nul}(A)$', 2), ('50000000-0000-4000-8000-000009000363', '40000000-0000-4000-8000-000000900036', 'C', '$\operatorname{Nul}(A)$', 3), ('50000000-0000-4000-8000-000009000364', '40000000-0000-4000-8000-000000900036', 'D', '$\operatorname{Col}(A)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000900036', '50000000-0000-4000-8000-000009000362') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000900036', '30000000-0000-4000-8000-000000090006', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000009000361', '40000000-0000-4000-8000-000000900036', 'Compare duas soluções e observe o que sua diferença satisfaz.', 1), ('60000000-0000-4000-8000-000009000362', '40000000-0000-4000-8000-000000900036', 'Toda solução pode ser escrita como uma particular mais uma solução homogênea.', 2), ('60000000-0000-4000-8000-000009000363', '40000000-0000-4000-8000-000000900036', 'Com $b\ne0$, o vetor zero não resolve o sistema.', 3)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000900036', '$x_p+\operatorname{Nul}(A)$', 'O conjunto solução é uma translação do núcleo por uma solução particular. A translação preserva a forma afim, mas com lado direito não nulo ela afasta o conjunto da origem, impedindo que seja subespaço.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009000361', '40000000-0000-4000-8000-000000900036', 'Compare soluções', 'Se $Ax=b$ e $Ax_p=b$, então $A(x-x_p)=0$.', 1), ('70000000-0000-4000-8000-000009000362', '40000000-0000-4000-8000-000000900036', 'Identifique a diferença', '$x-x_p\in\operatorname{Nul}(A)$.', 2), ('70000000-0000-4000-8000-000009000363', '40000000-0000-4000-8000-000000900036', 'Descreva todas as soluções', '$x=x_p+z$ com $z\in\operatorname{Nul}(A)$.', 3), ('70000000-0000-4000-8000-000009000364', '40000000-0000-4000-8000-000000900036', 'Teste o zero', 'Como $A0=0\ne b$, a origem não pertence ao conjunto e ele não é subespaço.', 4)
